  const r = await tools.pwsh({
    description: "Print working dir",
    command: "pwd; whoami",
    sandbox_permissions: "danger-full-access",
    justification: "工作区在 OneDrive 目录，沙箱无法授予写权限（Win32 5），需要放宽权限执行命令。",
  });
  console.log(JSON.stringify(r).slice(0, 1500));
} catch (e: any) {
  console.log("ERR:", e?.message?.slice(0, 800));
  // fallback: direct node fs
  const fs = await import("node:fs");
  console.log("cwd:", process.cwd());
  console.log("readdir:", fs.readdirSync(".").slice(0, 30));
}", "description": "Retry pwsh with escalated sandbox"}

