{"code": "const fs = await import("node:fs");
const raw = fs.readFileSync("_session.jsonl", "utf8").trim().split("\n").map(l => JSON.parse(l));
const out: string[] = [];
const clip = (s: string, n = 600) => s.replace(/\s+/g, " ").trim().slice(0, n);
for (const r of raw) {
  const p = r.payload ?? {};
  const t = r.timestamp?.slice(11, 19);
  if (r.type === "session_meta") { out.push(`## META cwd=${p.cwd} model=${p.model_provider} cli=${p.cli_version}`); continue; }
  if (r.type === "response_item" && p.type === "message") {
    const text = (p.content ?? []).map((c: any) => c.text ?? "").join("\n");
    out.push(`[${t}] ${p.role.toUpperCase()}: ${clip(text, p.role === "user" ? 3000 : 700)}`);
  } else if (r.type === "response_item" && (p.type === "custom_tool_call" || p.type === "function_call")) {
    const input = typeof p.input === "string" ? p.input : JSON.stringify(p.arguments ?? p.input);
    out.push(`[${t}] TOOL ${p.name}: ${clip(String(input), 260)}`);
  } else if (r.type === "event_msg" && p.type === "thread_goal_updated") {
    out.push(`[${t}] GOAL: ${clip(JSON.stringify(p.goal ?? p), 500)}`);
  } else if (r.type === "response_item" && p.type === "agent_message") {
    out.push(`[${t}] AGENT_MSG: ${clip(JSON.stringify(p).slice(0, 500), 400)}`);
  } else if (r.type === "compacted") {
    out.push(`[${t}] === COMPACTED ===`);
  }
}
fs.writeFileSync("_digest.md", out.join("\n"), "utf8");
console.log("digest lines:", out.length, "chars:", out.join("\n").length);
console.log(out.filter(x => x.includes("USER:")).length, "user msgs");", "description": "Build readable digest of session"}

