{"code": "const fs = await import("node:fs");
const text = fs.readFileSync("_session.jsonl", "utf8");
const pats: [string, RegExp][] = [
  ["sk-", /sk-[A-Za-z0-9_-]{16,}/g],
  ["ghp/gho", /gh[pou]_[A-Za-z0-9]{20,}/g],
  ["AKID", /AKID[A-Za-z0-9]{10,}/g],
  ["Bearer", /Bearer\s+[A-Za-z0-9._-]{20,}/g],
  ["password=", /password["']?\s*[:=]\s*["'][^"']{6,}["']/gi],
  ["AUTH_TOKEN=", /ANTHROPIC_AUTH_TOKEN=\S+/g],
  ["private key", /-----BEGIN [A-Z ]*PRIVATE KEY-----/g],
  ["email", /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g],
  ["ip", /\b(?:\d{1,3}\.){3}\d{1,3}\b/g],
];
for (const [name, re] of pats) {
  const m = text.match(re) ?? [];
  const uniq = [...new Set(m)].slice(0, 8);
  console.log(name, m.length, JSON.stringify(uniq));
}", "description": "Scan session log for secrets and PII"}

