{"code": "const fs = await import("node:fs");
const base = "D:\\Shervin\\OneDrive\\文档\\deepseek-harness\\default-workspace\\open-claude-code\\";
const req = fs.readFileSync(base + "docs/REQUIREMENTS_ALIGNMENT.md", "utf8");
const rows = req.split("\n").filter(l => /^\|\s*(ID|SES|MOD|RAG|PROT|APR|SUB|UX|BENCH|OPS|KNW|ADM|SEC)-?\d*/.test(l));
const statuses: Record<string, number> = {};
const ids: string[] = [];
for (const l of rows) {
  const cells = l.split("|").map(s => s.trim());
  const id = cells[1] ?? "";
  const st = cells[4] ?? "";
  if (!/^\w{2,5}-\d+$/.test(id)) continue;
  ids.push(id);
  statuses[st] = (statuses[st] || 0) + 1;
}
console.log("ids:", ids.length, ids.join(","));
console.log("statuses:", statuses);
console.log("=== TODO head ===");
const todo = fs.readFileSync(base + "TODO.md", "utf8").split("\n").slice(0, 40).join("\n");
console.log(todo);", "description": "Tally requirement statuses and read TODO head"}

