out.push(`> 系统提示（developer 角色，每轮重复）已省略；工具调用只保留命令摘要；原始记录见同目录 \`.jsonl\`。`);
out.push("");
const fmt = (iso: string) => new Date(iso).toLocaleString("sv-SE", { timeZone: "Asia/Shanghai" });
const t0 = raw[0]?.timestamp, t1 = raw[raw.length - 1]?.timestamp;
