out.push(`- 记录条数：${raw.length}`);
out.push("");
out.push("---");
out.push("");

let lastTool = "";
for (const r of raw) {
  const p = r.payload ?? {};
  const ts = fmt(r.timestamp);
  if (r.type === "response_item" && p.type === "message") {
    const text = (p.content ?? []).map((c: any) => c.text ?? "").join("").trim();
    if (!text) continue;
    if (p.role === "developer") continue;
    if (p.role === "user") {
      if (text.includes("<environment_context>") || text.includes("<codex_internal_context source=\"goal\">")) continue;
      out.push(`### 👤 用户 · ${ts}`);
      out.push("");
      out.push(text.length > 4000 ? text.slice(0, 4000) + "\n\n…（截断）" : text);
      out.push("");
    } else if (p.role === "assistant") {
      out.push(`### 🤖 助手 · ${ts}`);
      out.push("");
      out.push(text);
      out.push("");
    }
  } else if (r.type === "response_item" && (p.type === "custom_tool_call" || p.type === "function_call")) {
    const input = typeof p.input === "string" ? p.input : JSON.stringify(p.arguments ?? "");
    const m = input.match(/cmd:"((?:[^"\\]|\\.)*)"/);
    const cmd = m ? m[1].replace(/\\n/g, " ").replace(/\\"/g, '"') : input;
