    if (line.slice(0, 80) !== lastTool.slice(0, 80)) out.push(`- ${line}`);
    lastTool = line;
  } else if (r.type === "event_msg" && p.type === "thread_goal_updated") {
    out.push("");
    out.push(`**GOAL ${p.goal?.status ?? ""}** · token=${p.goal?.tokensUsed ?? "?"} · ${ts}`);
    out.push("");
  }
}
fs.mkdirSync(path.join(repo, "docs/handover/sessions"), { recursive: true });
const md = out.join("\n");
fs.writeFileSync(path.join(repo, "docs/handover/sessions/01a1af39-f0d7-7b03-aa48-e4552a4059a1_transcript.md"), md, "utf8");
fs.copyFileSync("_session.jsonl", path.join(repo, "docs/handover/sessions/01a1af39-f0d7-7b03-aa48-e4552a4059a1.jsonl"));
console.log("transcript chars:", md.length, "lines:", md.split("\n").length);", "description": "Generate session transcript and archive raw log"}

