{"code": "const fs = await import("node:fs");
const path = await import("node:path");
const root = "C:\\Users\\shers\\.dsh";
const now = Date.now();
const hits: { p: string; size: number; mtime: string }[] = [];
function walk(d: string, depth: number) {
  if (depth > 4) return;
  let items: any[] = [];
  try { items = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
  for (const it of items) {
    const p = path.join(d, it.name);
    try {
      const st = fs.statSync(p);
      if (it.isDirectory()) { if (it.name !== "node_modules") walk(p, depth + 1); }
      else if (now - st.mtimeMs < 45 * 60 * 1000 && st.size > 20000) hits.push({ p, size: st.size, mtime: new Date(st.mtimeMs).toISOString() });
    } catch {}
  }
}
walk(root, 0);
console.log(hits.sort((a, b) => b.size - a.size).slice(0, 15));", "description": "Find recently written DSH logs"}

