function decodeMulti(p: string) {
  const buf = fs.readFileSync(p);
  const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const offs: number[] = [];
  let i = 0;
  while ((i = buf.indexOf(magic, i)) !== -1) { offs.push(i); i += 4; }
  let out = "";
  for (let k = 0; k < offs.length; k++) {
    const end = k + 1 < offs.length ? offs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(offs[k], end)).toString("utf8"); } catch {}
  }
  return out;
}
const cands = ["session-e66aa1ca-62a5-4568-a971-1098e0096eeb", "session-a3e1f28a-0c2e-47d4-8a65-1466b6bdcbcb", "session-95e3bafa-5b72-4109-acdc-8957d70d3230", "session-2367d02c-ab0e-44aa-a40f-ef4d9bcd5ff4", "session-2d5fdd51-e7e2-4420-bfee-9b0313ea0a03"];
