out.push("> 这是执行「腾讯云项目 → GitHub → 学校云」任务的 DSH 会话（2026-11-06 15:45 起）。");
out.push("> 只保留用户消息、助手正文和工具调用摘要；模型的内部推理与工具原始输出保存在同目录 `.jsonl`。");
out.push("");
out.push("---");
out.push("");
const fmt = (t: number) => new Date(t).toLocaleString("sv-SE", { timeZone: "Asia/Shanghai" });
for (const r of recs) {
  const d = r.data ?? {};
  if (r.type === "user/message") {
    const text = (d.content ?? []).filter((c: any) => c.type === "text").map((c: any) => c.text).join("\n").trim();
    if (!text) continue;
    out.push(`### 👤 用户 · ${fmt(r.time)}`);
    out.push("");
    out.push(text);
    out.push("");
  } else if (r.type === "assistant/message") {
    const msg = d.message ?? {};
    const text = (msg.content ?? []).filter((c: any) => c.type === "text").map((c: any) => c.text).join("\n").trim();
    if (!text) continue;
    out.push(`### 🤖 助手 · ${fmt(r.time)}`);
    out.push("");
    out.push(text);
    out.push("");
  } else if (r.type === "tool/call") {
    const args = String(d.arguments ?? "");
    let summary = args;
    try { const o = JSON.parse(args); summary = o.description ?? o.command ?? args; } catch {}
    out.push(`- 🛠 \`${d.name}\` · ${fmt(r.time).slice(11)} · ${String(summary).replace(/\s+/g, " ").slice(0, 140)}`);
  }
}
const dir = path.join(repo, "docs/handover/sessions");
fs.writeFileSync(path.join(dir, "dsh-session-a3e1f28a_transcript.md"), out.join("\n"), "utf8");
fs.writeFileSync(path.join(dir, "dsh-session-a3e1f28a.jsonl"), recs.map(r => JSON.stringify(r)).join("\n") + "\n", "utf8");
console.log("transcript chars:", out.join("\n").length, "records:", recs.length, "raw bytes:", fs.statSync(path.join(dir, "dsh-session-a3e1f28a.jsonl")).size);", "description": "Export this window's session transcript and raw log"}

